import importlib.util,os,sys,subprocess
from pathlib import Path
required={'onnx':'onnx','onnxruntime':'onnxruntime','cv2':'opencv-python-headless','PIL':'pillow','requests':'requests'}
missing=[p for m,p in required.items() if importlib.util.find_spec(m) is None]
if missing:subprocess.check_call([sys.executable,'-m','pip','install','-q',*missing])
code=Path('/tmp/indra-det-code');(code/'indra_ocr').mkdir(parents=True,exist_ok=True)
(code/'train.py').write_text('"""Detector fine-tune: on a damaged page, do what the original detector does on the clean page.\n\nEvery step shows the frozen original detector a clean page and the student a damaged copy of it, and the student learns\nthe teacher\'s output: line core, top and bottom distance. So its behaviour on clean pages is the reference, and what a\nline is stays as Indra defines it. Damage follows lowq.py\'s chain (fewer pixels, noise, heavy JPEG) with blur, low\ncontrast, uneven light and blotches.\n\nData: synthetic pages (font families disjoint per split) and real receipts, train and validation only; held-out test\nreceipts never reach Kaggle and are scored locally through the whole pipeline.\nSelection: box agreement with the teacher\'s clean boxes at IoU .5, .7 and .85, on validation pages at lowq.py\'s levels.\nExact box position matters: with hand-checked boxes the held-out fields rise far more than recall alone explains.\nThe original detector is an eligible candidate.\n\nDRY_RUN=1 runs the whole pipeline on CPU with a tiny subset (local check, no Kaggle).\n"""\nimport collections\nimport hashlib\nimport itertools\nimport json\nimport math\nimport multiprocessing as mp\nimport os\nimport random\nimport shutil\nimport subprocess\nimport tarfile\nimport time\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\nimport requests\nimport torch\nfrom torch.nn import functional as F\nfrom torch.utils.data import DataLoader, Dataset, WeightedRandomSampler\n\nfrom det_post import INPUT_MULTIPLE, decode, page_to_input\nfrom det_trainable import DetNet, verify_parity\nfrom lowq import LEVELS, lower_quality\n\nDRY = os.environ.get("DRY_RUN") == "1"\nINPUT = Path(os.environ.get("KAGGLE_INPUT", "/kaggle/input"))\nOUT = Path(os.environ.get("KAGGLE_OUT", "/kaggle/working"))\nTMP = Path(os.environ.get("TRAIN_TMP", "/tmp/det-train"))\nTMP.mkdir(parents=True, exist_ok=True)\nSEED = 20261120\nLONG_SIDE = 1024  # meta.json det_long_side\nBATCH = 2 if DRY else 8\nTRAIN_SECONDS = float(os.environ.get("TRAIN_SECONDS", 40 if DRY else 2400))  # per candidate\nEVAL_EVERY = 20 if DRY else 400\nREAL_SHARE = .4  # of training samples\nVALID_SYNTHETIC = 4 if DRY else 120\nMODEL_REV = "bd02167fdf2005a19962cc15188f8496a2c87d3b"\nEVAL_LEVELS = {"original": .25, "light": .3, "medium": .3, "heavy": .15}  # selection weights; extreme is shown, not selected on\nIOUS = (.5, .7, .85)\nCONFIGS = [{"name": "steady", "lr": 1e-4, "anchor": 1e-5, "pos": 1.0},\n           {"name": "recall", "lr": 1e-4, "anchor": 1e-5, "pos": 2.0},\n           {"name": "bold", "lr": 3e-4, "anchor": 0.0, "pos": 1.0},\n           {"name": "gentle", "lr": 3e-5, "anchor": 1e-5, "pos": 1.0}]\ncv2.setNumThreads(1)\ntorch.set_num_threads(2)\n\n\ndef start_model():\n    found = os.environ.get("DET_START")\n    if found:\n        return Path(found)\n    path = TMP / "det.onnx"\n    if not path.exists():\n        r = requests.get(f"https://huggingface.co/datalab-to/indra-ocr/resolve/{MODEL_REV}/det.onnx", timeout=180)\n        r.raise_for_status()\n        path.write_bytes(r.content)\n    return path\n\n\nORIGINAL = start_model()\nprint("START", ORIGINAL, hashlib.sha256(ORIGINAL.read_bytes()).hexdigest()[:16], flush=True)\n\n# ------------------------------------------------------------------ pages\nt0 = time.monotonic()\nreal_path = next(INPUT.rglob("real-pages.json"))\nreal = json.loads(real_path.read_text(encoding="utf8"))\nsynth_path = next(INPUT.rglob("synthetic-pages.json"))\nsynth = json.loads(synth_path.read_text(encoding="utf8"))\nPAGES = TMP / "pages"\nPAGES.mkdir(exist_ok=True)\nif not any(PAGES.iterdir()):  # the input disk can be slow on Kaggle: work from a local copy\n    with tarfile.open(next(INPUT.rglob("synthetic-pages.tar"))) as tar:\n        tar.extractall(PAGES, filter="data")\n    print("CACHE synthetic", round(time.monotonic() - t0), "s", flush=True)\n    for row in real:\n        shutil.copyfile(real_path.parent / row["file"], PAGES / row["file"])\nassert all(r["split"] in ("train", "validation") for r in real), "a held-out receipt reached training"\nassert not {r["font"] for r in synth if r["split"] == "train"} & {r["font"] for r in synth if r["split"] == "validation"}\nITEMS = {s: [{"path": PAGES / r["file"], "skew": r["skew"], "source": "real"} for r in real if r["split"] == s]\n         + [{"path": PAGES / r["file"], "skew": 0.0, "source": "synthetic"} for r in synth if r["split"] == s] for s in ("train", "validation")}\nif DRY:\n    ITEMS["train"] = ITEMS["train"][:8] + ITEMS["train"][-8:]\nprint("PAGES", {s: dict(collections.Counter(i["source"] for i in v)) for s, v in ITEMS.items()}, round(time.monotonic() - t0), "s", flush=True)\n\n\ndef read_page(item):\n    """BGR page, straightened as the pipeline straightens it."""\n    a = cv2.imread(str(item["path"]), cv2.IMREAD_COLOR)\n    if abs(item["skew"]) >= .3:  # pipeline.DESKEW_MIN\n        h, w = a.shape[:2]\n        a = cv2.warpAffine(a, cv2.getRotationMatrix2D((w / 2, h / 2), item["skew"], 1.0), (w, h), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)\n    return a\n\n\ndef to_gray(a):\n    return cv2.cvtColor(a, cv2.COLOR_BGR2GRAY)\n\n\ndef to_input(gray, nh, nw):\n    """page_to_input at a size already chosen, so the damaged page lines up with the clean one."""\n    h, w = gray.shape\n    if (h, w) != (nh, nw):\n        gray = cv2.resize(gray, (nw, nh), interpolation=cv2.INTER_AREA if nh < h else cv2.INTER_LINEAR)\n    out = np.zeros((math.ceil(nh / INPUT_MULTIPLE) * INPUT_MULTIPLE, math.ceil(nw / INPUT_MULTIPLE) * INPUT_MULTIPLE), np.float32)\n    out[:nh, :nw] = 1.0 - gray.astype(np.float32) / 255.0\n    return out\n\n\ndef damage(a, rs):\n    """A random page damage. Severity is drawn once so size, noise and compression go together, as in lowq.LEVELS:\n    severity .25, .5, .75 and 1 are close to light, medium, heavy and extreme."""\n    x = a.astype(np.float32)\n    h, w = a.shape[:2]\n    if rs.random() < .15:  # low contrast\n        x = 128 + (x - 128) * rs.uniform(.5, .9) + rs.uniform(-30, 30)\n    if rs.random() < .12:  # uneven light\n        x = x + (np.linspace(rs.uniform(-45, 15), rs.uniform(-45, 15), w)[None, :] + np.linspace(rs.uniform(-25, 15), rs.uniform(-25, 15), h)[:, None])[..., None]\n    if rs.random() < .08:  # blotchy paper\n        blotch = cv2.resize(rs.normal(0, 1, (max(2, h // 40), max(2, w // 40))).astype(np.float32), (w, h), interpolation=cv2.INTER_CUBIC)\n        x = x + rs.uniform(6, 18) * blotch[..., None]\n    x = np.clip(x, 0, 255).astype(np.uint8)\n    if rs.random() < .2:  # soft focus\n        x = cv2.GaussianBlur(x, (0, 0), rs.uniform(.5, 1.5))\n    severity = rs.random() ** 1.2\n    scale = float(np.clip(.25 ** severity * rs.uniform(.85, 1.15), .2, 1))\n    noise = 30 * severity * rs.uniform(.5, 1.3)\n    quality = int(np.clip((80 - 65 * severity) * rs.uniform(.8, 1.25), 10, 95))\n    return lower_quality(x, scale, noise, quality, rs)\n\n\nclass Pages(Dataset):\n    """Clean input, damaged input and the page\'s size in the input."""\n\n    def __init__(self, items):\n        self.items, self.count = items, itertools.count()\n\n    def __len__(self):\n        return len(self.items)\n\n    def __getitem__(self, i):\n        rs = np.random.default_rng((torch.initial_seed() % (1 << 62), next(self.count)))\n        a = read_page(self.items[i])\n        if rs.random() < .35:  # people crop their screenshots: text comes larger in the detector\'s input\n            h, w = a.shape[:2]\n            ch, cw = int(h * rs.uniform(.55, 1)), int(w * rs.uniform(.8, 1))\n            y, x = int(rs.integers(0, h - ch + 1)), int(rs.integers(0, w - cw + 1))\n            a = a[y:y + ch, x:x + cw]\n        clean, s = page_to_input(to_gray(a), LONG_SIDE)\n        h, w = a.shape[:2]\n        nh, nw = max(1, round(h * s)), max(1, round(w * s))\n        bad = clean if rs.random() < .1 else to_input(to_gray(damage(a, rs)), nh, nw)\n        return clean, bad, nh, nw\n\n\ndef collate(batch):\n    H, W = max(b[0].shape[0] for b in batch), max(b[0].shape[1] for b in batch)\n    clean, bad, valid = np.zeros((len(batch), 1, H, W), np.float32), np.zeros((len(batch), 1, H, W), np.float32), np.zeros((len(batch), H // 2, W // 2), np.float32)\n    for i, (c, d, nh, nw) in enumerate(batch):\n        clean[i, 0, :c.shape[0], :c.shape[1]] = c\n        bad[i, 0, :d.shape[0], :d.shape[1]] = d\n        valid[i, :math.ceil(nh / 2), :math.ceil(nw / 2)] = 1\n    return torch.from_numpy(clean), torch.from_numpy(bad), torch.from_numpy(valid)\n\n\ndef train_loader(seed):\n    items = ITEMS["train"]\n    n = collections.Counter(i["source"] for i in items)\n    p = [(REAL_SHARE if i["source"] == "real" else 1 - REAL_SHARE) / n[i["source"]] for i in items]\n    sampler = WeightedRandomSampler(p, 1_000_000, replacement=True, generator=torch.Generator().manual_seed(seed))\n    return DataLoader(Pages(items), BATCH, sampler=sampler, collate_fn=collate, num_workers=0 if DRY else 2, pin_memory=not DRY, persistent_workers=not DRY, drop_last=True)\n\n\ndef objective(s, t, valid, pos):\n    """Student s against teacher t, both [B, 3, h, w]: line core (BCE and Dice), then top and bottom distance relative to line height."""\n    p = torch.sigmoid(t[:, 0])\n    bce = (F.binary_cross_entropy_with_logits(s[:, 0], p, reduction="none") * valid * (1 + (pos - 1) * p)).sum() / valid.sum().clamp_min(1)\n    q = torch.sigmoid(s[:, 0]) * valid\n    dice = 1 - ((2 * (q * p).sum((1, 2)) + 1) / (q.sum((1, 2)) + (p * valid).sum((1, 2)) + 1)).mean()\n    core = (p > .5) & (valid > 0)\n    height = (t[:, 1] + t[:, 2]).clamp_min(2)\n    off = F.smooth_l1_loss(s[:, 1] / height, t[:, 1] / height, reduction="none", beta=.1) + F.smooth_l1_loss(s[:, 2] / height, t[:, 2] / height, reduction="none", beta=.1)\n    box = off[core].mean() if core.any() else off.sum() * 0\n    return bce, dice, box\n\n\n# ------------------------------------------------------------------ validation: fixed damage at lowq.py\'s levels\ndef validation_pages(teacher, device):\n    picks = [i for i in ITEMS["validation"] if i["source"] == "real"] + [i for i in ITEMS["validation"] if i["source"] == "synthetic"][:VALID_SYNTHETIC]\n    out = []\n    for item in picks:\n        a = read_page(item)\n        clean, s = page_to_input(to_gray(a), LONG_SIDE)\n        h, w = a.shape[:2]\n        nh, nw = max(1, round(h * s)), max(1, round(w * s))\n        inputs = {"original": clean}\n        rs_seed = int(hashlib.sha256(item["path"].name.encode()).hexdigest()[:8], 16)\n        for level in ("light", "medium", "heavy", "extreme"):\n            bad = lower_quality(a, *LEVELS[level], np.random.default_rng((rs_seed, list(LEVELS).index(level))))\n            inputs[level] = to_input(to_gray(bad), nh, nw)\n        with torch.inference_mode():\n            ref = decode(teacher(torch.from_numpy(clean)[None, None].to(device))[0].float().cpu().numpy())\n        out.append({"source": item["source"], "inputs": inputs, "ref": ref})\n    return out\n\n\ndef iou_matrix(a, b):\n    ix = np.clip(np.minimum(a[:, None, 2], b[None, :, 2]) - np.maximum(a[:, None, 0], b[None, :, 0]), 0, None)\n    iy = np.clip(np.minimum(a[:, None, 3], b[None, :, 3]) - np.maximum(a[:, None, 1], b[None, :, 1]), 0, None)\n    inter = ix * iy\n    area = lambda x: (x[:, 2] - x[:, 0]) * (x[:, 3] - x[:, 1])\n    return inter / np.maximum(area(a)[:, None] + area(b)[None, :] - inter, 1e-6)\n\n\ndef matches(pred, ref, thr):\n    if not len(pred) or not len(ref):\n        return 0\n    m = iou_matrix(ref, pred)\n    n = 0\n    for i in np.argsort(-m.max(1)):\n        j = int(m[i].argmax())\n        if m[i, j] >= thr:\n            n += 1\n            m[:, j] = -1\n    return n\n\n\n@torch.inference_mode()\ndef evaluate(model, pages, device):\n    model.eval()\n    tally = collections.Counter()\n    for page in pages:\n        for level, x in page["inputs"].items():\n            with torch.autocast(device.type, dtype=torch.float16, enabled=device.type == "cuda"):\n                out = model(torch.from_numpy(x)[None, None].to(device))\n            pred = decode(out[0].float().cpu().numpy())\n            for thr in IOUS:\n                key = (page["source"], level, thr)\n                tally[key + ("tp",)] += matches(pred, page["ref"], thr)\n                tally[key + ("n",)] += len(pred) + len(page["ref"])\n    return {f"{source}/{level}": float(np.mean([2 * tally[source, level, thr, "tp"] / max(1, tally[source, level, thr, "n"]) for thr in IOUS]))\n            for source in ("real", "synthetic") for level in page["inputs"]}\n\n\ndef score(metrics):\n    return sum(w * .5 * (metrics[f"real/{level}"] + metrics[f"synthetic/{level}"]) for level, w in EVAL_LEVELS.items())\n\n\ndef candidate(rank, config, queue):\n    device = torch.device(f"cuda:{rank}" if torch.cuda.is_available() and not DRY else "cpu")\n    if device.type == "cuda":\n        torch.cuda.set_device(device)\n    seed = SEED + 1000 * [c["name"] for c in CONFIGS].index(config["name"])\n    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed)\n    teacher = DetNet(ORIGINAL).to(device).eval().requires_grad_(False)\n    pages = validation_pages(teacher, device)\n    if not (OUT / "baseline.json").exists():  # the start model\'s own scores: eligible for selection\n        base = evaluate(teacher, pages, device)\n        (OUT / "baseline.json").write_text(json.dumps(base, indent=1))\n        print("BASELINE", round(score(base), 5), json.dumps({k: round(v, 3) for k, v in base.items()}), flush=True)\n    student = DetNet(ORIGINAL).to(device)\n    anchors = {n: p.detach().clone() for n, p in student.named_parameters()}\n    opt = torch.optim.AdamW(student.parameters(), lr=config["lr"], weight_decay=0)\n\n    def lr_at(frac):  # time-based: 3% warmup, cosine to lr/50 exactly at TRAIN_SECONDS\n        if frac < .03:\n            return config["lr"] * (.1 + .9 * frac / .03)\n        return config["lr"] * (.02 + .98 * .5 * (1 + math.cos(math.pi * min(1, (frac - .03) / .97))))\n    scaler = torch.amp.GradScaler(device.type, enabled=device.type == "cuda")\n    data = train_loader(seed)\n    start = last_eval = time.monotonic()\n    best, steps, run, log, done = -1.0, 0, collections.Counter(), [], False\n    while not done:\n        for clean, bad, valid in data:\n            student.train()\n            clean, bad, valid = clean.to(device, non_blocking=True), bad.to(device, non_blocking=True), valid.to(device, non_blocking=True)\n            with torch.autocast(device.type, dtype=torch.float16, enabled=device.type == "cuda"):\n                s = student(bad)\n                with torch.no_grad():\n                    t = teacher(clean)\n            bce, dice, box = objective(s.float(), t.float(), valid, config["pos"])\n            anchor = sum((p - anchors[n]).square().sum() for n, p in student.named_parameters())\n            loss = bce + dice + box + config["anchor"] * anchor\n            opt.zero_grad(set_to_none=True)\n            if not torch.isfinite(loss):\n                run["nonfinite_skipped"] += 1\n                continue\n            scaler.scale(loss).backward()\n            scaler.unscale_(opt)\n            torch.nn.utils.clip_grad_norm_(student.parameters(), 5)\n            for g in opt.param_groups:\n                g["lr"] = lr_at((time.monotonic() - start) / TRAIN_SECONDS)\n            scaler.step(opt)\n            scaler.update()\n            steps += 1\n            run.update({"loss": loss.item(), "bce": bce.item(), "dice": dice.item(), "box": box.item(), "anchor": anchor.item()})\n            now = time.monotonic()\n            if steps % (5 if DRY else 200) == 0:\n                print("STEP", json.dumps({"cand": config["name"], "steps": steps, "sec": round(now - start), "lr": opt.param_groups[0]["lr"], "sec_per_step": round((now - start) / steps, 3),\n                                          **{k: round(v / steps, 4) for k, v in run.items()}}), flush=True)\n            final = now - start > TRAIN_SECONDS\n            if now - last_eval > EVAL_EVERY or final:\n                metrics = evaluate(student, pages, device)\n                value = score(metrics)\n                row = {"config": config, "steps": steps, "seconds": round(now - start), "score": value, "validation": metrics}\n                log.append(row)\n                print("VALID", json.dumps({"cand": config["name"], "steps": steps, "score": round(value, 5), **{k: round(v, 3) for k, v in metrics.items()}}), flush=True)\n                if value > best:\n                    best = value\n                    torch.save({"state_dict": student.state_dict(), "selection": row}, OUT / f"ckpt-{config[\'name\']}.pt")\n                (OUT / f"history-{config[\'name\']}.json").write_text(json.dumps(log, indent=1))\n                last_eval = time.monotonic()\n            if final:\n                done = True\n                break\n    queue.put({"name": config["name"], "best": best, "steps": steps, "sec_per_step": (time.monotonic() - start) / max(steps, 1)})\n\n\nif __name__ == "__main__":\n    # Query GPUs without initialising CUDA here: forked candidates cannot use CUDA if the parent did.\n    gpus = [] if DRY else [l for l in subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout.splitlines() if l.startswith("GPU ")]\n    print("DEVICES", len(gpus), gpus, flush=True)\n    ctx = mp.get_context("fork")\n    queue = ctx.Queue()\n    configs = CONFIGS[:1] if DRY else CONFIGS\n    for wave in range(0, len(configs), max(1, len(gpus))):\n        procs = []\n        for rank, cfg in enumerate(configs[wave:wave + max(1, len(gpus))]):\n            p = ctx.Process(target=candidate, args=(rank, cfg, queue))\n            p.start()\n            procs.append(p)\n        for p in procs:\n            p.join()\n            assert p.exitcode == 0, f"candidate process failed ({p.exitcode})"\n    summaries = []\n    while not queue.empty():\n        summaries.append(queue.get())\n    print("CANDIDATES", json.dumps(summaries), flush=True)\n    parity = verify_parity(ORIGINAL)  # after the forks: keeps OpenMP out of the parent before fork\n    print("PARITY", json.dumps(parity), flush=True)\n\n    # ---------------- selection on validation only (the original is eligible)\n    base = json.loads((OUT / "baseline.json").read_text())\n    options = [("start", score(base), None)]\n    results = {"baseline": base, "start_parity": parity, "candidates": summaries, "configs": configs, "model_revision": MODEL_REV, "levels": EVAL_LEVELS, "ious": IOUS,\n               "pages": {s: dict(collections.Counter(i["source"] for i in v)) for s, v in ITEMS.items()}}\n    for cfg in configs:\n        path = OUT / f"ckpt-{cfg[\'name\']}.pt"\n        ckpt = torch.load(path, map_location="cpu", weights_only=False)\n        options.append((cfg["name"], ckpt["selection"]["score"], path))\n        results[f"selection_{cfg[\'name\']}"] = ckpt["selection"]\n        model = DetNet(ORIGINAL)\n        model.load_state_dict(ckpt["state_dict"])\n        model.write_onnx(ORIGINAL, OUT / f"det-{cfg[\'name\']}.onnx")\n        results[f"export_parity_{cfg[\'name\']}"] = verify_parity(OUT / f"det-{cfg[\'name\']}.onnx", model)\n    options.sort(key=lambda o: -o[1])\n    results["selected"] = options[0][0]\n    results["selection_scores"] = {n: s for n, s, _ in options}\n    print("SELECTION", json.dumps([(n, round(s, 5)) for n, s, _ in options]), "->", options[0][0], flush=True)\n    (OUT / "results.json").write_text(json.dumps(results, indent=1), encoding="utf8")\n    print("FINAL", json.dumps({"selected": options[0][0]}), flush=True)\n',encoding='utf8')
(code/'det_trainable.py').write_text('"""Indra\'s line detector (det.onnx, LineNet) rebuilt in PyTorch, with its weights and its exact output.\n\nThe export folded batch norm into the convolutions, so this net has none. Trained weights go back into a copy of the\noriginal ONNX graph, keeping every other node as shipped. verify_parity compares both.\n"""\nimport onnx\nimport torch\nfrom onnx import numpy_helper\nfrom torch import nn\nfrom torch.nn import functional as F\n\nDIST_SCALE = 8.0  # the Mul constant after Softplus in the graph\n\n\ndef conv_nodes(graph):\n    return [n for n in graph.node if n.op_type == "Conv"]\n\n\nclass DetNet(nn.Module):\n    """Convolutions in the graph\'s order; forward follows the graph\'s data flow."""\n\n    def __init__(self, path):\n        super().__init__()\n        graph = onnx.load(str(path)).graph\n        init = {t.name: numpy_helper.to_array(t) for t in graph.initializer}\n        self.convs = nn.ModuleList()\n        for node in conv_nodes(graph):\n            attrs = {a.name: onnx.helper.get_attribute_value(a) for a in node.attribute}\n            w, b = init[node.input[1]].copy(), init[node.input[2]].copy()\n            groups = attrs["group"]\n            c = nn.Conv2d(w.shape[1] * groups, w.shape[0], tuple(attrs["kernel_shape"]), tuple(attrs["strides"]), attrs["pads"][0], groups=groups)\n            c.weight.data = torch.from_numpy(w)\n            c.bias.data = torch.from_numpy(b)\n            self.convs.append(c)\n        assert len(self.convs) == 39, len(self.convs)\n\n    def run(self, x, *indices):\n        """Conv then HardSwish for each index; the last of a residual body has no activation (see res)."""\n        for i in indices:\n            x = F.hardswish(self.convs[i](x))\n        return x\n\n    def res(self, x, i):\n        return x + self.convs[i + 2](self.run(x, i, i + 1))\n\n    def forward(self, x):\n        stem = self.run(x, 0)\n        s0 = self.res(self.run(stem, 1, 2), 3)\n        s1 = self.res(self.res(self.run(s0, 6, 7), 8), 11)\n        s2 = self.res(self.res(self.run(s1, 14, 15), 16), 19)\n        s3 = self.res(self.res(self.run(s2, 22, 23), 24), 27)\n        p = self.run(s3, 30)\n        p = self.run(s2, 31) + F.interpolate(p, size=s2.shape[2:], mode="nearest")\n        p = self.run(s1, 32) + F.interpolate(p, size=s1.shape[2:], mode="nearest")\n        p = self.run(s0, 33) + F.interpolate(p, size=s0.shape[2:], mode="nearest")\n        p = self.run(p, 34)\n        fine = F.pixel_unshuffle(self.run(stem, 35), 2)\n        out = F.pixel_shuffle(self.convs[38](self.run(torch.cat([p, fine], 1), 36, 37)), 2)\n        return torch.cat([out[:, :1], F.softplus(out[:, 1:]) * DIST_SCALE], 1)\n\n    def write_onnx(self, template, path):\n        model = onnx.load(str(template))\n        init = {t.name: t for t in model.graph.initializer}\n        for node, conv in zip(conv_nodes(model.graph), self.convs):\n            for name, param in zip(node.input[1:3], (conv.weight, conv.bias)):\n                init[name].CopyFrom(numpy_helper.from_array(param.detach().cpu().numpy(), name))\n        onnx.save(model, str(path))\n\n\n@torch.inference_mode()\ndef verify_parity(path, model=None, atol=2e-3):\n    """Largest output difference between the ONNX graph and the PyTorch net, on noise and on a text-like page."""\n    import numpy as np\n    import onnxruntime as ort\n\n    model = (model or DetNet(path)).cpu().eval()\n    sess = ort.InferenceSession(str(path), providers=["CPUExecutionProvider"])\n    rs = np.random.default_rng(1)\n    worst = 0.0\n    bars = np.zeros((1, 1, 512, 320), np.float32)\n    bars[:, :, 40:60, 30:290] = 1\n    bars[:, :, 120:132, 60:250] = .7\n    for x in (rs.random((1, 1, 320, 224), np.float32), bars, rs.random((1, 1, 1024, 576), np.float32) * .2):\n        a = sess.run(None, {"x": x})[0]\n        b = model(torch.from_numpy(x)).numpy()\n        assert a.shape == b.shape, (a.shape, b.shape)\n        worst = max(worst, float(np.abs(a - b).max()))\n    assert worst < atol, worst\n    return {"max_abs": worst}\n',encoding='utf8')
(code/'det_post.py').write_text('"""Torch-free pre- and post-processing for LineNet (shared by training and inference).\n\nInference with ONNX Runtime needs only numpy and cv2, so these functions live\napart from the PyTorch model in det_model.py, which re-exports them.\n"""\n\nfrom __future__ import annotations\n\nimport math\n\nimport numpy as np\n\n# Target geometry, shared by training (encode) and inference (decode).\nCORE_FRAC = 0.4  # core band height as a fraction of the line ink height\nCORE_X_SHRINK = 0.15  # the core is shorter than the line by this fraction of its height, at each end\nOUT_STRIDE = 2\nINPUT_MULTIPLE = 32  # H and W must divide by this\n\n\n# ---------------------------------------------------------------------------\n# Input preprocessing (shared by training and inference)\n# ---------------------------------------------------------------------------\n\n\ndef page_to_input(gray: np.ndarray, long_side: int) -> tuple[np.ndarray, float]:\n    """Resize a uint8 grayscale page so its long side is ``long_side`` and pad\n    to a multiple of 32 with white.  Returns (float32 [H, W] ink map, scale)."""\n    import cv2\n\n    h, w = gray.shape\n    scale = long_side / max(h, w)\n    nh, nw = max(1, round(h * scale)), max(1, round(w * scale))\n    if (nh, nw) != (h, w):\n        interp = cv2.INTER_AREA if scale < 1 else cv2.INTER_LINEAR\n        gray = cv2.resize(gray, (nw, nh), interpolation=interp)\n    ph = math.ceil(nh / INPUT_MULTIPLE) * INPUT_MULTIPLE\n    pw = math.ceil(nw / INPUT_MULTIPLE) * INPUT_MULTIPLE\n    out = np.zeros((ph, pw), np.float32)  # ink map: 0 = white\n    out[:nh, :nw] = 1.0 - gray.astype(np.float32) / 255.0\n    return out, scale\n\n\n# ---------------------------------------------------------------------------\n# Targets\n# ---------------------------------------------------------------------------\n\n\ndef encode_targets(\n    boxes: np.ndarray,\n    in_hw: tuple[int, int],\n    valid_hw: tuple[int, int],\n    ignore: np.ndarray | None = None,\n):\n    """Build training targets at 1/2 resolution.\n\n    boxes:   [N, 4] line ink boxes in input pixels (x0, y0, x1, y1)\n    in_hw:   padded input size; valid_hw: size of the real page inside it\n    ignore:  [M, 4] regions with no loss, in input pixels\n\n    Returns core [h, w] float32, dist [2, h, w] float32, weight [h, w] float32\n    (0 on padding and ignore regions), and reg_mask [h, w] bool (core pixels).\n    """\n    s = OUT_STRIDE\n    h, w = in_hw[0] // s, in_hw[1] // s\n    core = np.zeros((h, w), np.float32)\n    dist = np.zeros((2, h, w), np.float32)\n    weight = np.zeros((h, w), np.float32)\n    weight[: math.ceil(valid_hw[0] / s), : math.ceil(valid_hw[1] / s)] = 1.0\n    if ignore is not None:\n        for x0, y0, x1, y1 in ignore:\n            weight[\n                max(0, int(y0 // s)) : max(0, math.ceil(y1 / s)),\n                max(0, int(x0 // s)) : max(0, math.ceil(x1 / s)),\n            ] = 0.0\n    # Larger lines first, so a small line drawn later keeps its own band.\n    order = np.argsort(-(boxes[:, 3] - boxes[:, 1])) if len(boxes) else []\n    ys = (np.arange(h, dtype=np.float32) + 0.5) * s  # pixel centres in input px\n    for i in order:\n        x0, y0, x1, y1 = boxes[i]\n        lh = y1 - y0\n        if lh < 2 or x1 - x0 < 2:\n            continue\n        cy = 0.5 * (y0 + y1)\n        half = 0.5 * CORE_FRAC * lh\n        r0 = max(0, int(math.floor((cy - half) / s)))\n        r1 = min(h, max(r0 + 1, int(math.ceil((cy + half) / s))))\n        sx = min(CORE_X_SHRINK * lh, 0.25 * (x1 - x0))\n        c0 = max(0, int(math.floor((x0 + sx) / s)))\n        c1 = min(w, max(c0 + 1, int(math.ceil((x1 - sx) / s))))\n        if r0 >= h or c0 >= w:\n            continue\n        core[r0:r1, c0:c1] = 1.0\n        dist[0, r0:r1, c0:c1] = (ys[r0:r1] - y0)[:, None]\n        dist[1, r0:r1, c0:c1] = (y1 - ys[r0:r1])[:, None]\n        # A line inside an ignore region is still a positive.\n        weight[r0:r1, c0:c1] = np.maximum(weight[r0:r1, c0:c1], 1.0)\n    return core, dist, weight, core > 0.5\n\n\n# ---------------------------------------------------------------------------\n# Decoding\n# ---------------------------------------------------------------------------\n\n\ndef decode(\n    out: np.ndarray,\n    thresh: float = 0.5,\n    min_area: int = 2,\n    grow_y: float = 0.0,\n    grow_x: float = 0.0,\n) -> np.ndarray:\n    """Decode one page.  out: [3, h, w] (core logit, top dist, bottom dist).\n\n    ``grow_y`` / ``grow_x`` widen every box by that fraction of its height\n    (each side), to absorb the +-1 px error of the 1/2-resolution output.\n\n    Returns [N, 5] boxes in input pixels: x0, y0, x1, y1, score."""\n    import cv2\n\n    prob = 1.0 / (1.0 + np.exp(-out[0]))\n    mask = (prob > thresh).astype(np.uint8)\n    n, lab, stats, _ = cv2.connectedComponentsWithStats(mask, connectivity=4)\n    if n <= 1:\n        return np.zeros((0, 5), np.float32)\n    s = OUT_STRIDE\n    flat = lab.ravel()\n    keep = flat > 0\n    idx = flat[keep]\n    ys = (np.indices(lab.shape)[0].ravel()[keep].astype(np.float32) + 0.5) * s\n    top = ys - out[1].ravel()[keep]\n    bot = ys + out[2].ravel()[keep]\n    sc = prob.ravel()[keep]\n    cnt = np.bincount(idx, minlength=n).astype(np.float32)\n    # Mean is a robust enough summary here and is far cheaper than a median.\n    y0 = np.bincount(idx, weights=top, minlength=n) / np.maximum(cnt, 1)\n    y1 = np.bincount(idx, weights=bot, minlength=n) / np.maximum(cnt, 1)\n    score = np.bincount(idx, weights=sc, minlength=n) / np.maximum(cnt, 1)\n    boxes = []\n    for i in range(1, n):\n        if stats[i, cv2.CC_STAT_AREA] < min_area:\n            continue\n        lh = max(1.0, y1[i] - y0[i])\n        ex = min(CORE_X_SHRINK * lh, 0.5 * lh)\n        x0 = stats[i, cv2.CC_STAT_LEFT] * s - ex\n        x1 = (stats[i, cv2.CC_STAT_LEFT] + stats[i, cv2.CC_STAT_WIDTH]) * s + ex\n        boxes.append(\n            (\n                x0 - grow_x * lh,\n                y0[i] - grow_y * lh,\n                x1 + grow_x * lh,\n                y1[i] + grow_y * lh,\n                score[i],\n            )\n        )\n    return np.asarray(boxes, np.float32).reshape(-1, 5)\n',encoding='utf8')
(code/'lowq.py').write_text('"""Low-quality copies of the real receipts: fewer pixels, then noise, then heavy JPEG compression, all at once.\n\n    .control-venv/bin/python receipts/real/lowq.py make      # writes /var/services/chatbot_x/receipt-tests-lowq/<level>/\n    PYTHONPATH=vendor/indra:v3:receipts .control-venv/bin/python receipts/real/lowq.py eval name=bundle ... [--out f.json]\n\neval scores the held-out test receipts only, through the whole pipeline: detection, reading, parsing.\n"""\nimport argparse\nimport collections\nimport hashlib\nimport json\nimport multiprocessing as mp\nimport re\nimport sys\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\n\nHERE = Path(__file__).parent\nR = Path("/var/services/chatbot_x/receipt-tests")\nOUT = Path("/var/services/chatbot_x/receipt-tests-lowq")\n# level: (share of original width and height, noise strength out of 255, JPEG quality)\nLEVELS = {"light": (.75, 5, 60), "medium": (.5, 12, 40), "heavy": (.35, 20, 25), "extreme": (.25, 30, 15)}\nFOLD = str.maketrans({"ي": "ی", "ى": "ی", "ك": "ک", "\u200c": "", "ـ": "", "٬": ",", "٠": "۰", "١": "۱", "٢": "۲", "٣": "۳", "٤": "۴", "٥": "۵", "٦": "۶", "٧": "۷", "٨": "۸", "٩": "۹",\n                      "0": "۰", "1": "۱", "2": "۲", "3": "۳", "4": "۴", "5": "۵", "6": "۶", "7": "۷", "8": "۸", "9": "۹"})\n\n\ndef norm(s):\n    return "".join(s.translate(FOLD).split())\n\n\ndef lower_quality(image, scale, noise, quality, rs):\n    """image: uint8 grayscale or BGR. Returns the re-encoded image, as a messenger or a cheap camera leaves it."""\n    h, w = image.shape[:2]\n    small = cv2.resize(image, (max(8, round(w * scale)), max(8, round(h * scale))), interpolation=cv2.INTER_AREA)\n    grain = rs.normal(0, noise, small.shape[:2]).astype(np.float32)  # same grain on all channels, as a sensor\'s brightness noise\n    noisy = small.astype(np.float32) + (grain[..., None] if small.ndim == 3 else grain)\n    speck = rs.random(small.shape[:2]) < noise / 1800  # sparse dark and bright specks on the background\n    noisy[speck] = rs.choice([0, 255], int(speck.sum()))[..., None] if small.ndim == 3 else rs.choice([0, 255], int(speck.sum()))\n    ok, buf = cv2.imencode(".jpg", np.clip(noisy, 0, 255).astype(np.uint8), [cv2.IMWRITE_JPEG_QUALITY, quality])\n    return cv2.imdecode(buf, cv2.IMREAD_UNCHANGED)\n\n\ndef receipts():\n    seen, out = set(), []\n    for p in sorted((p for p in R.iterdir() if not p.name.endswith("Identifier")), key=lambda p: (len(p.stem), p.stem)):\n        h = hashlib.sha256(p.read_bytes()).hexdigest()\n        if h not in seen:\n            seen.add(h)\n            out.append(p)\n    return out\n\n\ndef make():\n    for level, (scale, noise, quality) in LEVELS.items():\n        d = OUT / level\n        d.mkdir(parents=True, exist_ok=True)\n        total = 0\n        for p in receipts():\n            rs = np.random.default_rng(int(hashlib.sha256(f"{p.name}/{level}".encode()).hexdigest()[:8], 16))\n            out = lower_quality(cv2.imread(str(p), cv2.IMREAD_COLOR), scale, noise, quality, rs)\n            dest = d / (p.stem + ".jpg")\n            cv2.imencode(".jpg", out, [cv2.IMWRITE_JPEG_QUALITY, 95])[1].tofile(str(dest))  # keeps the damage; adds no more visible loss\n            total += dest.stat().st_size\n        print(f"{level:8s} {scale:.0%} size, noise {noise}, JPEG {quality}: {total / 1e6:.1f} MB", flush=True)\n    splits = json.loads((HERE / "splits.json").read_text(encoding="utf8"))\n    (OUT / "README.txt").write_text("Low-quality copies of receipt-tests, made by tune-ocr/receipts/real/lowq.py. Contains real names and card numbers: keep private.\\n"\n                                    "Levels are (size, noise, JPEG quality): " + json.dumps(LEVELS) + "\\nReceipts held out of training: " + json.dumps(splits["test_unseen_style"] + splits["test_seen_style"]) + "\\n", encoding="utf8")\n\n\n@dataclass\nclass Gold:\n    box: list\n    text: str\n    conf: float = 1.0\n\n\n@dataclass\nclass GoldPage:\n    lines: list\n\n\nFIELDS = ("amount", "fee", "date", "time", "tracking", "reference", "from_card", "to_card")\n\n\ndef field_value(f, key):\n    v = f.get(key)\n    if isinstance(v, dict):\n        v = v.get("value")\n    return None if v is None else norm(str(v))\n\n\ndef job(args):\n    bundle, level, name, gold = args\n    cv2.setNumThreads(1)\n    import indra_ocr\n    from receipt_ocr import parse, read\n\n    ocr = indra_ocr.load(path=bundle, threads=4, mode="ocr")\n    path = R / name if level == "original" else OUT / level / (Path(name).stem + ".jpg")\n    res = read(ocr, path)\n    truth = parse(GoldPage([Gold(g["box"], g["text"]) for g in gold]))["fields"]\n    pred = collections.Counter(norm(l["text"]) for l in res["lines"])\n    row = {"file": name, "level": level, "lines": len(gold), "hit": 0, "digit_lines": 0, "digit_hit": 0, "fields": 0, "fields_right": 0, "wrong_silent": 0, "per_field": {}, "wrong": [], "flags": len(res["checks"]), "page_warning": any(c["field"] == "page" for c in res["checks"])}\n    for g in gold:\n        n = norm(g["text"])\n        ok = pred[n] > 0\n        pred[n] -= ok\n        row["hit"] += ok\n        if any(c in "۰۱۲۳۴۵۶۷۸۹" for c in g["text"]):\n            row["digit_lines"] += 1\n            row["digit_hit"] += ok\n    flagged = {c["field"] for c in res["checks"]}\n    for key in FIELDS:\n        want = field_value(truth, key)\n        if want is None:\n            continue\n        got = field_value(res["fields"], key)\n        row["fields"] += 1\n        right = got == want\n        row["fields_right"] += right\n        row["per_field"][key] = right\n        warned = key in flagged or "page" in flagged  # the page warning covers every field on the page\n        if not right:\n            row["wrong"].append({"field": key, "want": want, "got": got, "flagged": warned})\n        if got is not None and not right and not warned:\n            row["wrong_silent"] += 1  # a wrong value that no check flagged: the dangerous case\n    return row\n\n\ndef evaluate(models, out, splits=("test",), levels=None):\n    levels = levels or ("original", *LEVELS)\n    rows = json.loads((HERE / "real-lines.json").read_text(encoding="utf8"))\n    gold = collections.defaultdict(list)\n    for r in rows:\n        if r["split"] in splits:\n            gold[r["file"]].append(r)\n    print("test receipts", len(gold), "lines", sum(map(len, gold.values())), flush=True)\n    report = {}\n    with mp.get_context("spawn").Pool(4) as pool:\n        for m in models:\n            name, bundle = m.split("=", 1)\n            results = pool.map(job, [(bundle, level, f, gold[f]) for level in levels for f in gold], chunksize=4)\n            report[name] = results\n            print(f"\\n{name}\\n{\'level\':10s}{\'all lines\':>11s}{\'digit lines\':>13s}{\'fields right\':>14s}{\'amounts\':>9s}{\'wrong, unflagged\':>18s}")\n            for level in levels:\n                xs = [r for r in results if r["level"] == level]\n                am = [r["per_field"]["amount"] for r in xs if "amount" in r["per_field"]]\n                print(f"{level:10s}{100 * sum(r[\'hit\'] for r in xs) / max(1, sum(r[\'lines\'] for r in xs)):10.1f}%{100 * sum(r[\'digit_hit\'] for r in xs) / max(1, sum(r[\'digit_lines\'] for r in xs)):12.1f}%"\n                      f"{100 * sum(r[\'fields_right\'] for r in xs) / max(1, sum(r[\'fields\'] for r in xs)):13.1f}%{100 * sum(am) / max(1, len(am)):8.1f}%{sum(r[\'wrong_silent\'] for r in xs):>12d} of {sum(r[\'fields\'] for r in xs)}", flush=True)\n    if out:\n        Path(out).write_text(json.dumps(report, ensure_ascii=False), encoding="utf8")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("action", choices=["make", "eval"])\n    ap.add_argument("models", nargs="*", help="name=bundle")\n    ap.add_argument("--out")\n    ap.add_argument("--splits", default="test", help="comma-separated: test,validation,train")\n    ap.add_argument("--levels", default="", help="comma-separated; default: all")\n    a = ap.parse_args()\n    if a.action == "make":\n        make()\n    else:\n        evaluate(a.models, a.out, tuple(a.splits.split(",")), tuple(a.levels.split(",")) if a.levels else None)\n\n\nif __name__ == "__main__":\n    main()\n',encoding='utf8')
env=dict(os.environ,PYTHONPATH=str(code))
subprocess.check_call([sys.executable,'-u',str(code/'train.py')],env=env,cwd=str(code))
